/* Recettes de la partie Repas, écrites pour l'entraînement. Quantités pour UNE portion,
   en grammes (crus) ; les valeurs nutritionnelles sont calculées à partir des aliments
   (lib/data/aliments.ts), jamais saisies à la main. Le régime (vegan, végétarien…) et les
   allergènes se déduisent aussi des ingrédients.
   m : moment (matin, repas, collation) · min : temps total · t : étiquettes
   (rapide, batch, budget, pre = avant la séance, post = après, dessert)
   mat : matériel nécessaire (plaques, four, micro, mixeur) · img : photo, à venir. */

export type Moment = "matin" | "repas" | "collation";
export type Etiquette = "rapide" | "batch" | "budget" | "pre" | "post" | "dessert";
export type Materiel = "plaques" | "four" | "micro" | "mixeur";
export type Recette = {
  id: string; n: string; en: string; m: Moment; min: number;
  t: Etiquette[]; mat: Materiel[];
  ing: [string, number][];
  e: string[]; ee: string[];
  note: string; noteEn: string;
  img?: string;
};

